export function AriaDemo({
  label = "{{label}}",
  checked = {{checked}},
  role = "{{role}}",
  accent = "{{accent}}",
  announce = {{announce}},
}) {
  const shape = {
    switch: { box: { width: 48, height: 26, borderRadius: 999 }, on: { transform: "translateX(22px)", opacity: 1 }, off: { opacity: 1 } },
    checkbox: { box: { width: 26, height: 26, borderRadius: 6 }, on: { opacity: 1 }, off: { opacity: 0 } },
    radio: { box: { width: 26, height: 26, borderRadius: "50%" }, on: { opacity: 1 }, off: { opacity: 0 } },
  }[role];
  return (
    <div style={{ width: 320, fontFamily: "system-ui, sans-serif", fontSize: 15, color: "#241430" }}>
      <div style={{ display: "flex", alignItems: "center", gap: 12 }}>
        <button type="button" role={role} aria-checked={checked} aria-label={label}
          style={{ position: "relative", border: "2px solid " + accent, background: "#FAF7F2", cursor: "pointer", padding: 0, ...shape.box }}>
          <span className="aria-thumb" style={{ position: "absolute", top: 2, left: 2, width: 18, height: 18, borderRadius: "50%", background: accent, ...(checked ? shape.on : shape.off) }} />
        </button>
        <span style={{ fontWeight: 600 }}>{label}</span>
      </div>
      <style>{`
        @media (prefers-reduced-motion: no-preference) {
          .aria-thumb { transition: transform .15s, opacity .15s; }
        }
      `}</style>
      {announce && <p style={{ margin: "10px 0 0", fontSize: 13, background: "#A8E6C133", borderLeft: "3px solid " + accent, padding: "8px 10px" }}>Screen reader: &ldquo;{label}, {role}, {String(checked)}&rdquo;</p>}
      <code style={{ display: "block", marginTop: 8, fontSize: 12, color: "#241430aa" }}>role="{role}" aria-checked="{String(checked)}"</code>
    </div>
  );
}
